import json
from pathlib import Path

def fill(selector,text): return {'\\''operation'\\'':'\\''fill'\\'','\\''selector'\\'':selector,'\\''text'\\'':text}
def click(selector): return {'\\''operation'\\'':'\\''click'\\'','\\''selector'\\'':selector}
def wait(selector): return {'\\''operation'\\'':'\\''wait'\\'','\\''selector'\\'':selector}
def shot(caption): return {'\\''operation'\\'':'\\''screenshot'\\'','\\''caption'\\'':caption}
def nav(url='\\''/'\\''): return {'\\''operation'\\'':'\\''navigate'\\'','\\''url'\\'':url}

scenarios=[]
scenarios.append({
 '\\''id'\\'':'\\''empty-cloud-shelf'\\'', '\\''url'\\'':'\\''/'\\'', '\\''target'\\'':'\\''remote'\\'', '\\''viewport'\\'':{'\\''width'\\'':1440,'\\''height'\\'':900},
 '\\''steps'\\'':[
   wait('\\''.empty-card'\\''),
   shot('\\''The newly migrated remote shelf opens empty on one desktop screen, with no login and the D1 + R2 cloud badge visible.'\\'')
 ]
})
scenarios.append({
 '\\''id'\\'':'\\''save-read-refresh-delete'\\'', '\\''url'\\'':'\\''/'\\'', '\\''target'\\'':'\\''remote'\\'', '\\''viewport'\\'':{'\\''width'\\'':1440,'\\''height'\\'':900},
 '\\''steps'\\'':[
   wait('\\''.empty-card'\\''),
   fill('\\''#title'\\'','\\''Greeting'\\''), fill('\\''#text'\\'','\\''Hello, team"'!'"'\\''), click('\\''#save-button'\\''), wait('\\''[data-title=\"Greeting\"]'\\''),
   fill('\\''#title'\\'','\\''Sign-off'\\''), fill('\\''#text'\\'','\\''Kind regards'\\''), click('\\''#save-button'\\''), wait('\\''[data-title=\"Sign-off\"]'\\''),
   click('\\''[data-title=\"Sign-off\"] .snippet-title'\\''), wait('\\''#reader[data-reader-state=\"ready\"]'\\''),
   shot('\\''Two cloud-backed snippets are listed, and selecting Sign-off shows its own Kind regards body.'\\''),
   nav('\\''/'\\''), wait('\\''[data-title=\"Sign-off\"]'\\''), click('\\''[data-title=\"Sign-off\"] .snippet-title'\\''), wait('\\''#reader[data-reader-state=\"ready\"]'\\''),
   shot('\\''After a page reload, both saved titles return and Sign-off opens again from cloud storage.'\\''),
   click('\\''[data-title=\"Sign-off\"] .delete-button'\\''), wait('\\''#status[data-status=\"success\"]'\\''),
   click('\\''[data-title=\"Greeting\"] .snippet-title'\\''), wait('\\''#reader[data-reader-state=\"ready\"]'\\''),
   shot('\\''After deleting Sign-off, Greeting remains listed and readable with Hello, team"'!.'"'\\'')
 ]
})
scenarios.append({
 '\\''id'\\'':'\\''fresh-browser-continuity'\\'', '\\''url'\\'':'\\''/'\\'', '\\''target'\\'':'\\''remote'\\'', '\\''viewport'\\'':{'\\''width'\\'':1440,'\\''height'\\'':900},
 '\\''steps'\\'':[
   wait('\\''[data-title=\"Greeting\"]'\\''),
   shot('\\''A fresh browser context rebuilds the unchanged cloud shelf with Greeting listed, Sign-off absent, and no reader selection carried over.'\\''),
   click('\\''[data-title=\"Greeting\"] .snippet-title'\\''), wait('\\''#reader[data-reader-state=\"ready\"]'\\''),
   shot('\\''Selecting Greeting in the fresh context reads Hello, team"'! from the remote shelf.'"'\\'')
 ]
})
scenarios.append({
 '\\''id'\\'':'\\''both-validation-errors'\\'', '\\''url'\\'':'\\''/'\\'', '\\''target'\\'':'\\''remote'\\'', '\\''viewport'\\'':{'\\''width'\\'':1440,'\\''height'\\'':900},
 '\\''steps'\\'':[
   wait('\\''[data-title=\"Greeting\"]'\\''),
   fill('\\''#text'\\'','\\''Hello'\\''), click('\\''#save-button'\\''), wait('\\''#status[data-status=\"error\"]'\\''),
   shot('\\''Submitting text without a title shows the title-required error and leaves Greeting as the only saved snippet.'\\''),
   fill('\\''#title'\\'','\\''Empty note'\\''), fill('\\''#text'\\'','\\''   '\\''), click('\\''#save-button'\\''),
   shot('\\''Submitting Empty note with spaces-only text shows the text-required error and leaves the cloud shelf unchanged.'\\'')
 ]
})
scenarios.append({
 '\\''id'\\'':'\\''plain-text-markup'\\'', '\\''url'\\'':'\\''/'\\'', '\\''target'\\'':'\\''remote'\\'', '\\''viewport'\\'':{'\\''width'\\'':1440,'\\''height'\\'':900},
 '\\''steps'\\'':[
   wait('\\''[data-title=\"Greeting\"]'\\''),
   fill('\\''#title'\\'','\\''Markup sample'\\''), fill('\\''#text'\\'','\\''<b>Hello</b>'\\''), click('\\''#save-button'\\''), wait('\\''[data-title=\"Markup sample\"]'\\''),
   click('\\''[data-title=\"Markup sample\"] .snippet-title'\\''), wait('\\''#reader[data-reader-state=\"ready\"]'\\''),
   shot('\\''Markup-looking content is displayed literally as <b>Hello</b> in the plain-text reader.'\\'')
 ]
})
capacity_steps=[wait('\\''[data-title=\"Markup sample\"]'\\'')]
# Greeting and Markup sample reserve 24 bytes. These 16 saves reach the exact 1,048,576-byte approved ceiling.
for i in range(1,17):
    title=f'\\''Capacity {i:02d}'\\''
    body='\\''x'\\''*(65512 if i==1 else 65536)
    capacity_steps += [fill('\\''#title'\\'',title), fill('\\''#text'\\'',body), click('\\''#save-button'\\''), wait(f'\\''[data-title=\"{title}\"]'\\'')]
capacity_steps += [
 fill('\\''#title'\\'','\\''Overflow'\\''), fill('\\''#text'\\'','\\''Cannot fit'\\''), click('\\''#save-button'\\''), wait('\\''#save-recovery:not([hidden])'\\''),
 shot('\\''A real remote save beyond the approved capacity is rejected with a clear no-capacity message, the form preserved, and no success state.'\\''),
 click('\\''#start-new-save'\\'')
]
for i in range(1,17):
    title=f'\\''Capacity {i:02d}'\\''
    capacity_steps += [click(f'\\''[data-title=\"{title}\"] .delete-button'\\''), wait('\\''#status[data-status=\"success\"]'\\'')]
scenarios.append({
 '\\''id'\\'':'\\''real-failed-save-and-cleanup'\\'', '\\''url'\\'':'\\''/'\\'', '\\''target'\\'':'\\''remote'\\'', '\\''viewport'\\'':{'\\''width'\\'':1440,'\\''height'\\'':900},
 '\\''steps'\\'':capacity_steps
})
scenarios.append({
 '\\''id'\\'':'\\''final-cloud-state'\\'', '\\''url'\\'':'\\''/'\\'', '\\''target'\\'':'\\''remote'\\'', '\\''viewport'\\'':{'\\''width'\\'':1440,'\\''height'\\'':900},
 '\\''steps'\\'':[
   wait('\\''[data-title=\"Greeting\"]'\\''), wait('\\''[data-title=\"Markup sample\"]'\\''),
   shot('\\''After capacity-fixture cleanup, a new browser context shows only the two intended cloud snippets and an empty reader.'\\''),
   click('\\''[data-title=\"Markup sample\"] .snippet-title'\\''), wait('\\''#reader[data-reader-state=\"ready\"]'\\''),
   shot('\\''The final remote shelf opens Markup sample as literal plain text while Greeting remains listed.'\\'')
 ]
})
req={'\\''action'\\'':'\\''demo'\\'','\\''requestId'\\'':'\\''final-demo-v2'\\'','\\''scenarios'\\'':scenarios}
Path('\\''/deos/output/requests/final-demo-v2.json'\\'').write_text(json.dumps(req,ensure_ascii=False,indent=2)+'\\''\\n'\\'')
print('\\''saved'\\'',len(scenarios),'\\''scenarios'\\'',sum(len(s['\\''steps'\\'']) for s in scenarios),'\\''steps'\\'',Path('\\''/deos/output/requests/final-demo-v2.json'\\'').stat().st_size,'\\''bytes'\\'')
PY
deos-implementation --wait /deos/output/requests/final-demo-v2.json'"

